// Outside [HeroIcons] on purpose: the icon tree shaker skips the body of a @staticIconProvider
// class, so the accent constants must be referenced from here to stay in the release font.
IconData? _accentOf(IconData icon) {
  if (icon.fontFamily != HeroIcons.fontFamily) return null;
  final IconData? accent = switch (icon.codePoint) {
    0xE022 => HeroIcons.homeAccent,
    0xE024 => HeroIcons.bagAccent,
    0xE025 => HeroIcons.cartAccent,
    0xE027 => HeroIcons.basketAccent,
    0xE028 => HeroIcons.storeAccent,
    0xE029 => HeroIcons.ordersAccent,
    0xE02B => HeroIcons.receiptAccent,
    0xE02C => HeroIcons.deliveryAccent,
    0xE02E => HeroIcons.pinAccent,
    0xE030 => HeroIcons.clockAccent,
    0xE032 => HeroIcons.calendarAccent,
    0xE034 => HeroIcons.starAccent,
    0xE036 => HeroIcons.pointsAccent,
    0xE038 => HeroIcons.heartAccent,
    0xE03A => HeroIcons.giftAccent,
    0xE03B => HeroIcons.tagAccent,
    0xE03C => HeroIcons.voucherAccent,
    0xE03E => HeroIcons.discountAccent,
    0xE03F => HeroIcons.walletAccent,
    0xE040 => HeroIcons.savingsAccent,
    0xE041 => HeroIcons.crownAccent,
    0xE042 => HeroIcons.boltAccent,
    0xE043 => HeroIcons.flameAccent,
    0xE045 => HeroIcons.sparkleAccent,
    0xE046 => HeroIcons.rocketAccent,
    0xE049 => HeroIcons.personAccent,
    0xE04A => HeroIcons.peopleAccent,
