    0xE01E => HeroIcons.historyAccent,
    0xE01F => HeroIcons.copyAccent,
    0xE020 => HeroIcons.editAccent,
    0xE021 => HeroIcons.trashAccent,
    0xE02A => HeroIcons.ordersDoneAccent,
    0xE031 => HeroIcons.hourglassAccent,
    0xE033 => HeroIcons.calendarCheckAccent,
    0xE048 => HeroIcons.categoryAccent,
    0xE04C => HeroIcons.phoneAccent,
    0xE04F => HeroIcons.chatAddAccent,
    0xE056 => HeroIcons.unlockAccent,
    0xE057 => HeroIcons.lockClockAccent,
    0xE05B => HeroIcons.languageAccent,
    0xE05E => HeroIcons.micAccent,
    0xE05F => HeroIcons.stopAccent,
    0xE060 => HeroIcons.stopCircleAccent,
    0xE063 => HeroIcons.thumbUpAccent,
    0xE065 => HeroIcons.thumbDownAccent,
    0xE067 => HeroIcons.tapAccent,
