/// The natural colour of a two-tone icon's accent layer ([HeroIcons.fillOf]), after the sticker
/// art in `assets/svg`. The app maps each value to an `AppColors` token.
enum HeroIconFill {
  /// Brand green, saturated: the brand's own objects (bag, cart, store, delivery, pin, leaf).
  green,

  /// Pale brand mint: soft containers (chat, orders, clock face, person).
  mint,

  /// Gold: value and rewards (star, points, wallet, crown, voucher).
  amber,

  /// Sunny yellow: light and attention (bell, lightbulb, sun, bolt).
  yellow,

  /// Warm orange: treats and heat (gift, tag, flame).
  orange,

  /// Offer red: love and deals (heart, discount), stop and cancel.
  red,

  /// Pale sky blue: information, tools and glass (search lens, mail, info, lock).
  sky,

  /// Pale violet: Pro and magic (sparkle).
  violet,

  /// Warm cream: paper, pantry and utensils (egg, coffee, edit, copy).
  cream,
}
